WITH with_last AS (SELECT s.id, s.city, s.region, s.sqft, x.revenue, x.sale_date FROM stores s JOIN LATERAL (SELECT c.revenue, c.sale_date FROM store_sales c WHERE c.store_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, city, region, sqft, sale_date, CASE WHEN city RLIKE '^(Chiang Mai|New York)$' THEN 'GROUP_B' WHEN city RLIKE '^(Bangkok|Singapore)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS city_zone FROM with_last;
